"""dialogues between the 6 roster characters (210 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'dialogue', 'text': 'Vasilescu ! Toujours debout à cette heure ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0001_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0001', 'turn': 1, 'speaker': 'A', 'context': 'nocturnal'},
    {'cat': 'dialogue', 'text': 'Mon cher colonel, je ne me lève jamais avant le coucher du soleil.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0001_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0001', 'turn': 2, 'speaker': 'B', 'context': 'nocturnal'},
    {'cat': 'dialogue', 'text': 'Fichtre. Et la messe, le dimanche ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0001_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0001', 'turn': 3, 'speaker': 'A', 'context': 'nocturnal'},
    {'cat': 'dialogue', 'text': "Je l'évite. Les cierges me donnent mauvaise mine.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0001_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0001', 'turn': 4, 'speaker': 'B', 'context': 'nocturnal'},
    {'cat': 'dialogue', 'text': 'Vous avez servi dans la cavalerie, je crois ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0002_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0002', 'turn': 1, 'speaker': 'A', 'context': 'wolves'},
    {'cat': 'dialogue', 'text': "Vingt ans en selle, monsieur le comte. J'en ai encore les jambes arquées.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0002_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0002', 'turn': 2, 'speaker': 'B', 'context': 'wolves'},
    {'cat': 'dialogue', 'text': 'Chez nous, dans les Carpates, les loups montent mieux que vos dragons.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0002_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0002', 'turn': 3, 'speaker': 'A', 'context': 'wolves'},
    {'cat': 'dialogue', 'text': 'Les loups ne montent pas à cheval, voyons !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0002_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0002', 'turn': 4, 'speaker': 'B', 'context': 'wolves'},
    {'cat': 'dialogue', 'text': "Goûtez-moi ce gigot, Vasilescu. À l'ail, comme à la caserne.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0003_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0003', 'turn': 1, 'speaker': 'A', 'context': 'garlic'},
    {'cat': 'dialogue', 'text': "Merci, je ne touche jamais à l'ail. Une vieille allergie de famille.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0003_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0003', 'turn': 2, 'speaker': 'B', 'context': 'garlic'},
    {'cat': 'dialogue', 'text': 'Toute la famille ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0003_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0003', 'turn': 3, 'speaker': 'A', 'context': 'garlic'},
    {'cat': 'dialogue', 'text': 'Depuis le quinzième siècle.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0003_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0003', 'turn': 4, 'speaker': 'B', 'context': 'garlic'},
    {'cat': 'dialogue', 'text': "Colonel, vous n'apparaissez pas dans ce miroir.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0004_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0004', 'turn': 1, 'speaker': 'A', 'context': 'mirror'},
    {'cat': 'dialogue', 'text': 'Quoi ? Mais si, regardez, je suis là !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0004_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0004', 'turn': 2, 'speaker': 'B', 'context': 'mirror'},
    {'cat': 'dialogue', 'text': "Ah oui. Pardon, c'était moi qui n'y étais pas. Une vieille habitude.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0004_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0004', 'turn': 3, 'speaker': 'A', 'context': 'mirror'},
    {'cat': 'dialogue', 'text': 'Colonel, racontez-moi encore Verdun.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0005_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0005', 'turn': 1, 'speaker': 'A', 'context': 'verdun'},
    {'cat': 'dialogue', 'text': "Volontiers. C'était en seize, il pleuvait comme ce soir...", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0005_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0005', 'turn': 2, 'speaker': 'B', 'context': 'verdun'},
    {'cat': 'dialogue', 'text': 'Vous voyez ? Je la connais déjà par cœur.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0005_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0005', 'turn': 3, 'speaker': 'A', 'context': 'verdun'},
    {'cat': 'dialogue', 'text': "Mademoiselle, votre robe est d'un vert... réglementaire.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0006_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0006', 'turn': 1, 'speaker': 'A', 'context': 'green'},
    {'cat': 'dialogue', 'text': "C'est un compliment, colonel ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0006_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0006', 'turn': 2, 'speaker': 'B', 'context': 'green'},
    {'cat': 'dialogue', 'text': "Dans ma bouche, c'est le plus beau.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0006_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0006', 'turn': 3, 'speaker': 'A', 'context': 'green'},
    {'cat': 'dialogue', 'text': "On dit que vous n'avez jamais vu le front, colonel.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0007_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0007', 'turn': 1, 'speaker': 'A', 'context': 'never war'},
    {'cat': 'dialogue', 'text': 'Qui dit ça ? Donnez-moi un nom !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0007_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0007', 'turn': 2, 'speaker': 'B', 'context': 'never war'},
    {'cat': 'dialogue', 'text': 'Votre épouse.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0007_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0007', 'turn': 3, 'speaker': 'A', 'context': 'never war'},
    {'cat': 'dialogue', 'text': "Ah. Elle n'y était pas non plus, elle.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0007_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0007', 'turn': 4, 'speaker': 'B', 'context': 'never war'},
    {'cat': 'dialogue', 'text': 'Ce jazz ! On dirait une charge de cavalerie dans une cuisine.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0008_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0008', 'turn': 1, 'speaker': 'A', 'context': 'jazz'},
    {'cat': 'dialogue', 'text': 'Dansez donc, colonel, ça vous détendra.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0008_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0008', 'turn': 2, 'speaker': 'B', 'context': 'jazz'},
    {'cat': 'dialogue', 'text': "Je ne danse qu'au son du clairon.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0008_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0008', 'turn': 3, 'speaker': 'A', 'context': 'jazz'},
    {'cat': 'dialogue', 'text': "Je vais demander à l'orchestre s'ils en ont un.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0008_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0008', 'turn': 4, 'speaker': 'B', 'context': 'jazz'},
    {'cat': 'dialogue', 'text': 'Jeune homme, votre queue-de-pie traîne presque par terre.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0009_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0009', 'turn': 1, 'speaker': 'A', 'context': 'tails'},
    {'cat': 'dialogue', 'text': "C'est la mode, colonel. Londres, cette saison.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0009_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0009', 'turn': 2, 'speaker': 'B', 'context': 'tails'},
    {'cat': 'dialogue', 'text': 'À Londres, ils ne savent même pas monter à cheval.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0009_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0009', 'turn': 3, 'speaker': 'A', 'context': 'tails'},
    {'cat': 'dialogue', 'text': 'Une partie de cartes, colonel ? Petite mise.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0010_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0010', 'turn': 1, 'speaker': 'A', 'context': 'cards'},
    {'cat': 'dialogue', 'text': 'Je ne joue plus depuis Sedan.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0010_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0010', 'turn': 2, 'speaker': 'B', 'context': 'cards'},
    {'cat': 'dialogue', 'text': "Qu'avez-vous perdu à Sedan ?", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0010_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0010', 'turn': 3, 'speaker': 'A', 'context': 'cards'},
    {'cat': 'dialogue', 'text': 'Mon cheval, ma montre et ma dignité. Dans cet ordre.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0010_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0010', 'turn': 4, 'speaker': 'B', 'context': 'cards'},
    {'cat': 'dialogue', 'text': 'Vous avez fait votre service, au moins ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0011_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0011', 'turn': 1, 'speaker': 'A', 'context': 'service'},
    {'cat': 'dialogue', 'text': "J'ai servi... le champagne, surtout.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0011_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0011', 'turn': 2, 'speaker': 'B', 'context': 'service'},
    {'cat': 'dialogue', 'text': "Ah, la jeunesse d'aujourd'hui !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0011_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0011', 'turn': 3, 'speaker': 'A', 'context': 'service'},
    {'cat': 'dialogue', 'text': "Elle a soif, colonel. Comme celle d'hier.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0011_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0011', 'turn': 4, 'speaker': 'B', 'context': 'service'},
    {'cat': 'dialogue', 'text': "Colonel, vous me prêteriez cent francs jusqu'à demain ?", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0012_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0012', 'turn': 1, 'speaker': 'A', 'context': 'loan'},
    {'cat': 'dialogue', 'text': 'Demain, nous serons encore sur cette île, jeune homme.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0012_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0012', 'turn': 2, 'speaker': 'B', 'context': 'loan'},
    {'cat': 'dialogue', 'text': 'Justement. Vous ne risquez pas de me perdre de vue.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0012_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0012', 'turn': 3, 'speaker': 'A', 'context': 'loan'},
    {'cat': 'dialogue', 'text': 'Vous, là, le masqué ! Vous étiez dans quel régiment ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0013_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0013', 'turn': 1, 'speaker': 'A', 'context': 'regiment'},
    {'cat': 'dialogue', 'text': 'Celui de la nuit, colonel.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0013_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0013', 'turn': 2, 'speaker': 'B', 'context': 'regiment'},
    {'cat': 'dialogue', 'text': 'Connais pas. Mauvaise discipline, sûrement.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0013_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0013', 'turn': 3, 'speaker': 'A', 'context': 'regiment'},
    {'cat': 'dialogue', 'text': 'Colonel. Vous avez vu passer un homme en imperméable ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0014_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0014', 'turn': 1, 'speaker': 'A', 'context': 'raincoats'},
    {'cat': 'dialogue', 'text': "J'en ai vu trois. Ils marchent comme des fantassins.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0014_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0014', 'turn': 2, 'speaker': 'B', 'context': 'raincoats'},
    {'cat': 'dialogue', 'text': "C'est bien ce que je craignais.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0014_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0014', 'turn': 3, 'speaker': 'A', 'context': 'raincoats'},
    {'cat': 'dialogue', 'text': "Retirez donc ce masque, qu'on voie à qui on parle !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0015_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0015', 'turn': 1, 'speaker': 'A', 'context': 'unmask'},
    {'cat': 'dialogue', 'text': 'Tout le monde est masqué, ce soir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0015_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0015', 'turn': 2, 'speaker': 'B', 'context': 'unmask'},
    {'cat': 'dialogue', 'text': 'Oui, mais vous, on dirait que vous le portez aussi le jour.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0015_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0015', 'turn': 3, 'speaker': 'A', 'context': 'unmask'},
    {'cat': 'dialogue', 'text': 'Le jour, je dors.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0015_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0015', 'turn': 4, 'speaker': 'B', 'context': 'unmask'},
    {'cat': 'dialogue', 'text': 'Vous avez de bons yeux, colonel ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0016_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0016', 'turn': 1, 'speaker': 'A', 'context': 'left eye'},
    {'cat': 'dialogue', 'text': "Les meilleurs du régiment. Enfin, l'œil gauche.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0016_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0016', 'turn': 2, 'speaker': 'B', 'context': 'left eye'},
    {'cat': 'dialogue', 'text': "Alors surveillez la porte du bureau. Avec l'œil gauche.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0016_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0016', 'turn': 3, 'speaker': 'A', 'context': 'left eye'},
    {'cat': 'dialogue', 'text': "Alors, mon colonel, on m'offre un verre ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0017_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0017', 'turn': 1, 'speaker': 'A', 'context': 'drink'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, un officier offre toujours le premier verre.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0017_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0017', 'turn': 2, 'speaker': 'B', 'context': 'drink'},
    {'cat': 'dialogue', 'text': 'Et le deuxième ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0017_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0017', 'turn': 3, 'speaker': 'A', 'context': 'drink'},
    {'cat': 'dialogue', 'text': "Le deuxième, c'est la cantinière.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0017_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0017', 'turn': 4, 'speaker': 'B', 'context': 'drink'},
    {'cat': 'dialogue', 'text': 'Je vous ai vue au Moulin Rouge, en vingt-neuf.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0018_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0018', 'turn': 1, 'speaker': 'A', 'context': 'moulin rouge'},
    {'cat': 'dialogue', 'text': "Ah ? Et qu'est-ce que vous en avez pensé ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0018_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0018', 'turn': 2, 'speaker': 'B', 'context': 'moulin rouge'},
    {'cat': 'dialogue', 'text': "Rien du tout. J'avais les yeux fermés. Ma femme était assise à côté.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0018_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0018', 'turn': 3, 'speaker': 'A', 'context': 'moulin rouge'},
    {'cat': 'dialogue', 'text': 'Tu chantes, toi, mon colonel ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0019_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0019', 'turn': 1, 'speaker': 'A', 'context': 'madelon'},
    {'cat': 'dialogue', 'text': 'Seulement « La Madelon ». Et faux.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0019_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0019', 'turn': 2, 'speaker': 'B', 'context': 'madelon'},
    {'cat': 'dialogue', 'text': 'Parfait, on fera un duo. Moi aussi je chante faux, après minuit.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0019_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0019', 'turn': 3, 'speaker': 'A', 'context': 'madelon'},
    {'cat': 'dialogue', 'text': "Ces plumes sur votre masque, c'est du paon ?", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0020_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0020', 'turn': 1, 'speaker': 'A', 'context': 'peacock'},
    {'cat': 'dialogue', 'text': "Du paon, oui. Il ne s'en est jamais remis.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0020_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0020', 'turn': 2, 'speaker': 'B', 'context': 'peacock'},
    {'cat': 'dialogue', 'text': "Ha ! Il y a de l'esprit dans ce poulailler.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0020_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0020', 'turn': 3, 'speaker': 'A', 'context': 'peacock'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Sandra, vous avez un cou... remarquable.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0021_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0021', 'turn': 1, 'speaker': 'A', 'context': 'neck'},
    {'cat': 'dialogue', 'text': "On me l'a souvent dit, monsieur le comte.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0021_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0021', 'turn': 2, 'speaker': 'B', 'context': 'neck'},
    {'cat': 'dialogue', 'text': 'Rarement avec autant de sincérité, je parie.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0021_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0021', 'turn': 3, 'speaker': 'A', 'context': 'neck'},
    {'cat': 'dialogue', 'text': "On raconte que votre château n'a pas un seul miroir.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0022_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0022', 'turn': 1, 'speaker': 'A', 'context': 'no mirrors'},
    {'cat': 'dialogue', 'text': 'Les miroirs mentent, très chère. Moi, je ne mens jamais.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0022_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0022', 'turn': 2, 'speaker': 'B', 'context': 'no mirrors'},
    {'cat': 'dialogue', 'text': 'Alors dites-moi votre âge.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0022_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0022', 'turn': 3, 'speaker': 'A', 'context': 'no mirrors'},
    {'cat': 'dialogue', 'text': 'Ah. Il y a des limites à la sincérité.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0022_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0022', 'turn': 4, 'speaker': 'B', 'context': 'no mirrors'},
    {'cat': 'dialogue', 'text': 'Ce caviar vient de mes terres, sur le Danube.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0023_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0023', 'turn': 1, 'speaker': 'A', 'context': 'caviar'},
    {'cat': 'dialogue', 'text': 'Vous avez encore des terres, comte ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0023_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0023', 'turn': 2, 'speaker': 'B', 'context': 'caviar'},
    {'cat': 'dialogue', 'text': "J'ai encore le caviar. C'est déjà beaucoup.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0023_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0023', 'turn': 3, 'speaker': 'A', 'context': 'caviar'},
    {'cat': 'dialogue', 'text': 'Vous ne mangez rien, comte ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0024_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0024', 'turn': 1, 'speaker': 'A', 'context': 'late dinner'},
    {'cat': 'dialogue', 'text': 'Je dîne plus tard. Beaucoup plus tard.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0024_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0024', 'turn': 2, 'speaker': 'B', 'context': 'late dinner'},
    {'cat': 'dialogue', 'text': 'Au buffet de minuit ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0024_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0024', 'turn': 3, 'speaker': 'A', 'context': 'late dinner'},
    {'cat': 'dialogue', 'text': 'Quelque chose comme ça.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0024_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0024', 'turn': 4, 'speaker': 'B', 'context': 'late dinner'},
    {'cat': 'dialogue', 'text': 'Vasilescu, vous me devez une revanche au baccara.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0025_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0025', 'turn': 1, 'speaker': 'A', 'context': 'baccarat'},
    {'cat': 'dialogue', 'text': "Je ne joue qu'après minuit, mon jeune ami. La chance y est meilleure.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0025_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0025', 'turn': 2, 'speaker': 'B', 'context': 'baccarat'},
    {'cat': 'dialogue', 'text': 'Il est minuit passé.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0025_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0025', 'turn': 3, 'speaker': 'A', 'context': 'baccarat'},
    {'cat': 'dialogue', 'text': 'Alors préparez votre portefeuille.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0025_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0025', 'turn': 4, 'speaker': 'B', 'context': 'baccarat'},
    {'cat': 'dialogue', 'text': 'Votre queue-de-pie est très réussie, Victor. Pour un vivant.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0026_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0026', 'turn': 1, 'speaker': 'A', 'context': 'for a living man'},
    {'cat': 'dialogue', 'text': 'Pardon ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0026_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0026', 'turn': 2, 'speaker': 'B', 'context': 'for a living man'},
    {'cat': 'dialogue', 'text': 'Je disais : pour un soir de tempête.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0026_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0026', 'turn': 3, 'speaker': 'A', 'context': 'for a living man'},
    {'cat': 'dialogue', 'text': 'Comte, vous connaissiez Ashcombe avant ce soir ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0027_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0027', 'turn': 1, 'speaker': 'A', 'context': 'ancestors'},
    {'cat': 'dialogue', 'text': 'Je connaissais son grand-père. Et son arrière-grand-père.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0027_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0027', 'turn': 2, 'speaker': 'B', 'context': 'ancestors'},
    {'cat': 'dialogue', 'text': 'Vous les avez bien connus ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0027_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0027', 'turn': 3, 'speaker': 'A', 'context': 'ancestors'},
    {'cat': 'dialogue', 'text': 'Assez pour ne pas les regretter.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0027_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0027', 'turn': 4, 'speaker': 'B', 'context': 'ancestors'},
    {'cat': 'dialogue', 'text': 'Vous dormez bien, Victor ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0028_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0028', 'turn': 1, 'speaker': 'A', 'context': 'sleep'},
    {'cat': 'dialogue', 'text': 'Comme un bébé. Pourquoi ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0028_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0028', 'turn': 2, 'speaker': 'B', 'context': 'sleep'},
    {'cat': 'dialogue', 'text': "Pour rien. J'aime savoir qui dort profondément sous ce toit.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0028_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0028', 'turn': 3, 'speaker': 'A', 'context': 'sleep'},
    {'cat': 'dialogue', 'text': 'Vous aussi, vous préférez la nuit, monsieur ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0029_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0029', 'turn': 1, 'speaker': 'A', 'context': 'night'},
    {'cat': 'dialogue', 'text': 'La nuit, on voit mieux qui ment.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0029_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0029', 'turn': 2, 'speaker': 'B', 'context': 'night'},
    {'cat': 'dialogue', 'text': 'Et qui a soif.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0029_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0029', 'turn': 3, 'speaker': 'A', 'context': 'night'},
    {'cat': 'dialogue', 'text': 'Comte. Où étiez-vous pendant le dîner ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0030_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0030', 'turn': 1, 'speaker': 'A', 'context': 'memoirs'},
    {'cat': 'dialogue', 'text': 'Dans la bibliothèque. Je relisais mes mémoires.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0030_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0030', 'turn': 2, 'speaker': 'B', 'context': 'memoirs'},
    {'cat': 'dialogue', 'text': 'Ce sont des mémoires très longues.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0030_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0030', 'turn': 3, 'speaker': 'A', 'context': 'memoirs'},
    {'cat': 'dialogue', 'text': 'Quatre siècles, cela fait du volume.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0030_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0030', 'turn': 4, 'speaker': 'B', 'context': 'memoirs'},
    {'cat': 'dialogue', 'text': 'Votre masque est élégant. Que cachez-vous dessous ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0031_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0031', 'turn': 1, 'speaker': 'A', 'context': 'another mask'},
    {'cat': 'dialogue', 'text': 'Un autre masque.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0031_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0031', 'turn': 2, 'speaker': 'B', 'context': 'another mask'},
    {'cat': 'dialogue', 'text': "Ah ! Un homme selon mon cœur. Enfin, selon ce qu'il en reste.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0031_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0031', 'turn': 3, 'speaker': 'A', 'context': 'another mask'},
    {'cat': 'dialogue', 'text': 'Je vous surveille, Vasilescu.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0032_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0032', 'turn': 1, 'speaker': 'A', 'context': 'watching'},
    {'cat': 'dialogue', 'text': 'Tout le monde me surveille, mon ami. Personne ne me voit jamais.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0032_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0032', 'turn': 2, 'speaker': 'B', 'context': 'watching'},
    {'cat': 'dialogue', 'text': "T'as l'air pâlot, monsieur le comte. Tu veux un sandwich au jambon ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0033_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0033', 'turn': 1, 'speaker': 'A', 'context': 'ham sandwich'},
    {'cat': 'dialogue', 'text': 'Merci, mademoiselle. Je suis un régime... particulier.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0033_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0033', 'turn': 2, 'speaker': 'B', 'context': 'ham sandwich'},
    {'cat': 'dialogue', 'text': "À l'ail, alors ? C'est la spécialité de la cuisine.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0033_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0033', 'turn': 3, 'speaker': 'A', 'context': 'ham sandwich'},
    {'cat': 'dialogue', 'text': "Je vais prendre l'air, je crois.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0033_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0033', 'turn': 4, 'speaker': 'B', 'context': 'ham sandwich'},
    {'cat': 'dialogue', 'text': 'Vous chantez divinement, mademoiselle Odette.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0034_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0034', 'turn': 1, 'speaker': 'A', 'context': 'three walls'},
    {'cat': 'dialogue', 'text': "T'étais au cabaret ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0034_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0034', 'turn': 2, 'speaker': 'B', 'context': 'three walls'},
    {'cat': 'dialogue', 'text': 'Non. Je vous ai entendue à travers trois murs.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0034_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0034', 'turn': 3, 'speaker': 'A', 'context': 'three walls'},
    {'cat': 'dialogue', 'text': "Ah, c'est que je pousse, quand je m'y mets !", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0034_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0034', 'turn': 4, 'speaker': 'B', 'context': 'three walls'},
    {'cat': 'dialogue', 'text': "C'est vrai que tu dors dans un cercueil ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0035_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0035', 'turn': 1, 'speaker': 'A', 'context': 'coffin'},
    {'cat': 'dialogue', 'text': "Quelle idée ! Dans un sarcophage. C'est plus confortable.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0035_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0035', 'turn': 2, 'speaker': 'B', 'context': 'coffin'},
    {'cat': 'dialogue', 'text': 'Tu me fais marcher.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0035_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0035', 'turn': 3, 'speaker': 'A', 'context': 'coffin'},
    {'cat': 'dialogue', 'text': 'Jamais, mademoiselle. Je vous ferais plutôt danser.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0035_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0035', 'turn': 4, 'speaker': 'B', 'context': 'coffin'},
    {'cat': 'dialogue', 'text': 'Ces perles sont-elles vraies ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0036_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0036', 'turn': 1, 'speaker': 'A', 'context': 'pearls'},
    {'cat': 'dialogue', 'text': 'Autant que tes dents, monsieur le comte.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0036_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0036', 'turn': 2, 'speaker': 'B', 'context': 'pearls'},
    {'cat': 'dialogue', 'text': 'Alors elles sont très, très vraies.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0036_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0036', 'turn': 3, 'speaker': 'A', 'context': 'pearls'},
    {'cat': 'dialogue', 'text': "Victor, vous m'aviez promis la première valse.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0037_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0037', 'turn': 1, 'speaker': 'A', 'context': 'first waltz'},
    {'cat': 'dialogue', 'text': "Et je vous la donne. Le premier qui arrive, c'est moi.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0037_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0037', 'turn': 2, 'speaker': 'B', 'context': 'first waltz'},
    {'cat': 'dialogue', 'text': "Vous l'avez promise à trois femmes.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0037_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0037', 'turn': 3, 'speaker': 'A', 'context': 'first waltz'},
    {'cat': 'dialogue', 'text': 'Alors nous danserons à quatre.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0037_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0037', 'turn': 4, 'speaker': 'B', 'context': 'first waltz'},
    {'cat': 'dialogue', 'text': 'Sandra, qui est le monsieur en velours bordeaux ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0038_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0038', 'turn': 1, 'speaker': 'A', 'context': 'velvet'},
    {'cat': 'dialogue', 'text': 'Le comte Vasilescu. Un château, des terres, et aucun reflet.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0038_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0038', 'turn': 2, 'speaker': 'B', 'context': 'velvet'},
    {'cat': 'dialogue', 'text': 'Aucun reflet ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0038_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0038', 'turn': 3, 'speaker': 'A', 'context': 'velvet'},
    {'cat': 'dialogue', 'text': "Dans les miroirs. Personne n'ose en parler.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0038_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0038', 'turn': 4, 'speaker': 'B', 'context': 'velvet'},
    {'cat': 'dialogue', 'text': 'Votre montre a disparu de votre gilet, Victor.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0039_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0039', 'turn': 1, 'speaker': 'A', 'context': 'watch'},
    {'cat': 'dialogue', 'text': "Je l'ai prêtée.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0039_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0039', 'turn': 2, 'speaker': 'B', 'context': 'watch'},
    {'cat': 'dialogue', 'text': 'À un croupier, je suppose.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0039_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0039', 'turn': 3, 'speaker': 'A', 'context': 'watch'},
    {'cat': 'dialogue', 'text': 'Épousez-moi, Sandra.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0040_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0040', 'turn': 1, 'speaker': 'A', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': "Vous me l'avez déjà demandé l'an dernier.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0040_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0040', 'turn': 2, 'speaker': 'B', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': 'Et vous avez dit non.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0040_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0040', 'turn': 3, 'speaker': 'A', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': "Je n'ai pas changé d'avis. Mais j'adore qu'on me le redemande.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0040_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0040', 'turn': 4, 'speaker': 'B', 'context': 'proposal'},
    {'cat': 'dialogue', 'text': 'Qui êtes-vous, sous ce masque ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0041_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0041', 'turn': 1, 'speaker': 'A', 'context': 'deauville'},
    {'cat': 'dialogue', 'text': "Quelqu'un qui sait ce que vous avez fait à Deauville.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0041_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0041', 'turn': 2, 'speaker': 'B', 'context': 'deauville'},
    {'cat': 'dialogue', 'text': "Oh. Alors quelqu'un de très bien informé.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0041_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0041', 'turn': 3, 'speaker': 'A', 'context': 'deauville'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, ne restez pas seule ce soir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0042_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0042', 'turn': 1, 'speaker': 'A', 'context': 'advice'},
    {'cat': 'dialogue', 'text': "C'est une invitation ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0042_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0042', 'turn': 2, 'speaker': 'B', 'context': 'advice'},
    {'cat': 'dialogue', 'text': "C'est un conseil.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0042_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0042', 'turn': 3, 'speaker': 'A', 'context': 'advice'},
    {'cat': 'dialogue', 'text': "Dommage. J'aurais préféré l'invitation.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0042_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0042', 'turn': 4, 'speaker': 'B', 'context': 'advice'},
    {'cat': 'dialogue', 'text': 'Monsieur Minuit, vous qui voyez tout, qui a pris le collier ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0043_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0043', 'turn': 1, 'speaker': 'A', 'context': 'necklace'},
    {'cat': 'dialogue', 'text': 'Celui qui a le plus à perdre.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0043_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0043', 'turn': 2, 'speaker': 'B', 'context': 'necklace'},
    {'cat': 'dialogue', 'text': "Ce n'est pas une réponse, ça.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0043_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0043', 'turn': 3, 'speaker': 'A', 'context': 'necklace'},
    {'cat': 'dialogue', 'text': "C'est la seule que je donne gratuitement.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0043_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0043', 'turn': 4, 'speaker': 'B', 'context': 'necklace'},
    {'cat': 'dialogue', 'text': 'Votre robe est verte comme une émeraude volée.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0044_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0044', 'turn': 1, 'speaker': 'A', 'context': 'emerald'},
    {'cat': 'dialogue', 'text': 'Quel compliment étrange.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0044_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0044', 'turn': 2, 'speaker': 'B', 'context': 'emerald'},
    {'cat': 'dialogue', 'text': "Ce n'en était pas un.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0044_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0044', 'turn': 3, 'speaker': 'A', 'context': 'emerald'},
    {'cat': 'dialogue', 'text': 'Odette, ma chérie, quelle robe !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0045_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0045', 'turn': 1, 'speaker': 'A', 'context': 'pearls weight'},
    {'cat': 'dialogue', 'text': 'Merci. Trois kilos de perles, je sens plus mes épaules.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0045_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0045', 'turn': 2, 'speaker': 'B', 'context': 'pearls weight'},
    {'cat': 'dialogue', 'text': 'Il faut souffrir pour être admirée.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0045_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0045', 'turn': 3, 'speaker': 'A', 'context': 'pearls weight'},
    {'cat': 'dialogue', 'text': 'Ou pour être payée. Moi, je fais les deux.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0045_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0045', 'turn': 4, 'speaker': 'B', 'context': 'pearls weight'},
    {'cat': 'dialogue', 'text': "T'as vu le colonel ? Il me fait de l'œil depuis le dîner.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0046_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0046', 'turn': 1, 'speaker': 'A', 'context': 'colonel eye'},
    {'cat': 'dialogue', 'text': "Il fait de l'œil à toutes les femmes. Il n'en a qu'un de valide.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0046_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0046', 'turn': 2, 'speaker': 'B', 'context': 'colonel eye'},
    {'cat': 'dialogue', 'text': 'Alors je suis gâtée, il me le réserve.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0046_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0046', 'turn': 3, 'speaker': 'A', 'context': 'colonel eye'},
    {'cat': 'dialogue', 'text': 'Tu chantes, ce soir ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0047_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0047', 'turn': 1, 'speaker': 'A', 'context': 'singing rain'},
    {'cat': 'dialogue', 'text': "Si Ashcombe paie, je chante. S'il paie pas, je fredonne.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0047_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0047', 'turn': 2, 'speaker': 'B', 'context': 'singing rain'},
    {'cat': 'dialogue', 'text': "Et s'il pleut ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0047_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0047', 'turn': 3, 'speaker': 'A', 'context': 'singing rain'},
    {'cat': 'dialogue', 'text': 'Alors je chante sous la pluie, ça fait pleurer les riches.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0047_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0047', 'turn': 4, 'speaker': 'B', 'context': 'singing rain'},
    {'cat': 'dialogue', 'text': "Dis donc, Sandra, ton Victor, il a des dettes jusqu'au cou.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0048_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0048', 'turn': 1, 'speaker': 'A', 'context': 'victor debts'},
    {'cat': 'dialogue', 'text': "Ce n'est pas mon Victor.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0048_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0048', 'turn': 2, 'speaker': 'B', 'context': 'victor debts'},
    {'cat': 'dialogue', 'text': "Tant mieux. Il m'a tapé de l'argent, à moi aussi.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0048_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0048', 'turn': 3, 'speaker': 'A', 'context': 'victor debts'},
    {'cat': 'dialogue', 'text': 'Joli costume. Vous aussi, vous fuyez vos créanciers ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0049_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0049', 'turn': 1, 'speaker': 'A', 'context': 'creditors'},
    {'cat': 'dialogue', 'text': 'Je fuis la lumière.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0049_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0049', 'turn': 2, 'speaker': 'B', 'context': 'creditors'},
    {'cat': 'dialogue', 'text': "Moi aussi. Elle montre l'usure de mes poignets.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0049_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0049', 'turn': 3, 'speaker': 'A', 'context': 'creditors'},
    {'cat': 'dialogue', 'text': "Victor. Vous devez de l'argent à des gens dangereux.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0050_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0050', 'turn': 1, 'speaker': 'A', 'context': 'the amount'},
    {'cat': 'dialogue', 'text': 'Comment savez-vous mon nom ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0050_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0050', 'turn': 2, 'speaker': 'B', 'context': 'the amount'},
    {'cat': 'dialogue', 'text': 'Je connais aussi le montant.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0050_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0050', 'turn': 3, 'speaker': 'A', 'context': 'the amount'},
    {'cat': 'dialogue', 'text': 'Ah. Ne le dites pas trop fort, il est vexant.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0050_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0050', 'turn': 4, 'speaker': 'B', 'context': 'the amount'},
    {'cat': 'dialogue', 'text': 'Monsieur Minuit, un tuyau pour la roulette ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0051_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0051', 'turn': 1, 'speaker': 'A', 'context': 'roulette tip'},
    {'cat': 'dialogue', 'text': 'Rouge. Puis quittez la table.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0051_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0051', 'turn': 2, 'speaker': 'B', 'context': 'roulette tip'},
    {'cat': 'dialogue', 'text': 'Et si je gagne ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0051_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0051', 'turn': 3, 'speaker': 'A', 'context': 'roulette tip'},
    {'cat': 'dialogue', 'text': 'Quittez-la plus vite.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0051_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0051', 'turn': 4, 'speaker': 'B', 'context': 'roulette tip'},
    {'cat': 'dialogue', 'text': "Vous avez vu quelqu'un monter à l'étage ?", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0052_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0052', 'turn': 1, 'speaker': 'A', 'context': 'upstairs'},
    {'cat': 'dialogue', 'text': 'Une dame en vert et un monsieur en velours. Pas ensemble, je crois.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0052_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0052', 'turn': 2, 'speaker': 'B', 'context': 'upstairs'},
    {'cat': 'dialogue', 'text': "Merci. C'est tout ce que je voulais savoir.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0052_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0052', 'turn': 3, 'speaker': 'A', 'context': 'upstairs'},
    {'cat': 'dialogue', 'text': 'Odette, vous êtes la plus belle voix de Paris.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0053_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0053', 'turn': 1, 'speaker': 'A', 'context': 'sweet talk'},
    {'cat': 'dialogue', 'text': 'Et toi, le plus beau baratin de la soirée.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0053_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0053', 'turn': 2, 'speaker': 'B', 'context': 'sweet talk'},
    {'cat': 'dialogue', 'text': 'Ça se voit tant que ça ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0053_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0053', 'turn': 3, 'speaker': 'A', 'context': 'sweet talk'},
    {'cat': 'dialogue', 'text': "Ça s'entend, mon chou.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0053_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0053', 'turn': 4, 'speaker': 'B', 'context': 'sweet talk'},
    {'cat': 'dialogue', 'text': "Tu m'invites à danser, ou tu comptes encore tes dettes ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0054_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0054', 'turn': 1, 'speaker': 'A', 'context': 'counting'},
    {'cat': 'dialogue', 'text': 'Je peux faire les deux. Je compte en mesure.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0054_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0054', 'turn': 2, 'speaker': 'B', 'context': 'counting'},
    {'cat': 'dialogue', 'text': 'Alors un, deux, trois... et on oublie le reste.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0054_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0054', 'turn': 3, 'speaker': 'A', 'context': 'counting'},
    {'cat': 'dialogue', 'text': "On m'a dit que vous aviez débuté dans un bistrot de Montmartre.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0055_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0055', 'turn': 1, 'speaker': 'A', 'context': 'montmartre'},
    {'cat': 'dialogue', 'text': 'Sur une table de bistrot, même. Les chaises étaient trop basses.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0055_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0055', 'turn': 2, 'speaker': 'B', 'context': 'montmartre'},
    {'cat': 'dialogue', 'text': "Et aujourd'hui, le manoir Ashcombe.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0055_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0055', 'turn': 3, 'speaker': 'A', 'context': 'montmartre'},
    {'cat': 'dialogue', 'text': "Aujourd'hui, une table plus chère. C'est tout.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0055_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0055', 'turn': 4, 'speaker': 'B', 'context': 'montmartre'},
    {'cat': 'dialogue', 'text': "Le majordome m'a dit qu'Ashcombe allait annoncer un truc à minuit.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0056_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0056', 'turn': 1, 'speaker': 'A', 'context': 'midnight will'},
    {'cat': 'dialogue', 'text': 'Ses fiançailles ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0056_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0056', 'turn': 2, 'speaker': 'B', 'context': 'midnight will'},
    {'cat': 'dialogue', 'text': 'Son testament, plutôt.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0056_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0056', 'turn': 3, 'speaker': 'A', 'context': 'midnight will'},
    {'cat': 'dialogue', 'text': 'Ah. Je ferais bien de rester aimable, alors.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0056_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0056', 'turn': 4, 'speaker': 'B', 'context': 'midnight will'},
    {'cat': 'dialogue', 'text': 'Vous chantez à quelle heure, mademoiselle ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0057_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0057', 'turn': 1, 'speaker': 'A', 'context': 'front row'},
    {'cat': 'dialogue', 'text': 'À minuit, pardi. Ça te va bien, non ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0057_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0057', 'turn': 2, 'speaker': 'B', 'context': 'front row'},
    {'cat': 'dialogue', 'text': "Je serai là. Dans l'ombre.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0057_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0057', 'turn': 3, 'speaker': 'A', 'context': 'front row'},
    {'cat': 'dialogue', 'text': 'Mets-toi plutôt au premier rang, que je voie mon public.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0057_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0057', 'turn': 4, 'speaker': 'B', 'context': 'front row'},
    {'cat': 'dialogue', 'text': 'Dis donc, Monsieur Minuit, tu souris jamais ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0058_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0058', 'turn': 1, 'speaker': 'A', 'context': 'smile'},
    {'cat': 'dialogue', 'text': 'Seulement quand justice est faite.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0058_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0058', 'turn': 2, 'speaker': 'B', 'context': 'smile'},
    {'cat': 'dialogue', 'text': "Alors t'as pas dû sourire depuis longtemps, mon pauvre.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0058_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0058', 'turn': 3, 'speaker': 'A', 'context': 'smile'},
    {'cat': 'dialogue', 'text': 'Vous connaissez tout le monde, ici.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0059_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0059', 'turn': 1, 'speaker': 'A', 'context': 'secrets'},
    {'cat': 'dialogue', 'text': 'Je connais surtout leurs secrets. Les riches parlent beaucoup après un verre.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0059_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0059', 'turn': 2, 'speaker': 'B', 'context': 'secrets'},
    {'cat': 'dialogue', 'text': 'Vous me les direz ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0059_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0059', 'turn': 3, 'speaker': 'A', 'context': 'secrets'},
    {'cat': 'dialogue', 'text': 'Contre une danse. Et pas avec ce masque lugubre.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0059_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0059', 'turn': 4, 'speaker': 'B', 'context': 'secrets'},
    {'cat': 'dialogue', 'text': "T'as vu le type en imperméable ? Il me regarde comme si j'étais coupable.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0060_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0060', 'turn': 1, 'speaker': 'A', 'context': 'guilty'},
    {'cat': 'dialogue', 'text': "Vous l'êtes ?", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0060_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0060', 'turn': 2, 'speaker': 'B', 'context': 'guilty'},
    {'cat': 'dialogue', 'text': 'De rien du tout. Enfin, de rien de récent.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0060_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0060', 'turn': 3, 'speaker': 'A', 'context': 'guilty'},
]
